const points = $input.first().json?.result?.points ?? [];

if (points.length === 0) {
  return [{ json: { output: 'Информация по этой теме не найдена.', source: 'Неизвестно' } }];
}

const sorted = points.sort((a, b) => {
  const aFrom = a.payload?.metadata?.loc?.lines?.from ?? 0;
  const bFrom = b.payload?.metadata?.loc?.lines?.from ?? 0;
  return aFrom - bFrom;
});

const text = sorted
  .map(p => p.payload?.content ?? '')
  .filter(t => t.length > 0)
  .join('\n\n');

const humanNames = {
  '22_current_schedule_filled.md': 'Расписание потоков',
  '05_pricing_tariffs.md': 'Тарифы и цены',
  '06_booking_payment.md': 'Бронирование и оплата',
  '07_refund_policy.md': 'Политика возврата',
  '08_location_logistics.md': 'Локация и логистика',
  '09_accommodation_food.md': 'Проживание и питание',
  '10_packing_list.md': 'Список вещей',
  '11_checkin_checkout.md': 'Заезд и выезд',
  '15_participation_rules.md': 'Правила участия',
  '16_health_safety.md': 'Здоровье и безопасность',
  '18_pre_retreat_preparation.md': 'Подготовка к ретриту',
  '19_post_retreat_integration.md': 'Постретритная интеграция',
  '20_online_course.md': 'Онлайн-курс «Познай себя»',
  '23_postretrit_practices_checklist.md': 'Практики интеграции',
};

const sourceFile = points[0]?.payload?.metadata?.source ?? '';
const humanName = humanNames[sourceFile] ?? sourceFile;

return [{ json: { output: text, source: humanName } }];
